							<table width="100%" border="0"><tr>
								<td align="left" valign="middle"><a href="http://masslinemedia.com/smf/index.php?topic=578.msg9037#msg9037"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/post/xx.gif" alt="" border="0" /></a></td>
								<td align="left" valign="middle">
									<b><a href="http://masslinemedia.com/smf/index.php?topic=578.msg9037#msg9037">Re: campaign reform....</a></b>
									<div class="smalltext">&#171; <b>Reply #22 on:</b> December 17, 2006, 04:56:49 pm &#187;</div></td>
								<td align="right" valign="bottom" height="20" nowrap="nowrap" style="font-size: smaller;">
